-- A1.1 pre-flight (run on EACH target DB before `migrate deploy`; read-only). Every query must return the shown expectation.
-- P1 server >= 15 (NULLS NOT DISTINCT)                                   expect: true
SELECT current_setting('server_version_num')::int >= 150000 AS ok;
-- P2 no half-applied migration (else P3009)                               expect: 0
SELECT count(*) FROM "_prisma_migrations" WHERE finished_at IS NULL AND rolled_back_at IS NULL;
-- P3 base migration present, agency absent                                expect: t | f
SELECT bool_or(migration_name='20270201000100_trips' AND finished_at IS NOT NULL), bool_or(migration_name='20270201000200_agency') FROM "_prisma_migrations";
