-- P10 'PENDING_DELETE' is a TenantStatus label                            expect: 1
SELECT count(*) FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid WHERE t.typname = 'TenantStatus' AND e.enumlabel = 'PENDING_DELETE';
-- P11 sizes of the 5 existing tables touched (lock window estimate)
SELECT relname, n_live_tup FROM pg_stat_user_tables WHERE relname IN ('TripPickupZone','TripBooking','TripMoneyEvent','SellBasket','TripHold');
-- P12 nobody holds/queues locks on the 5 tables; no tx open > 30 s        expect: 0 rows
SELECT a.pid, a.state, now()-a.xact_start AS age, c.relname, l.mode FROM pg_locks l JOIN pg_class c ON c.oid = l.relation JOIN pg_stat_activity a ON a.pid = l.pid
 WHERE c.relname IN ('TripPickupZone','TripBooking','TripMoneyEvent','SellBasket','TripHold') AND a.pid <> pg_backend_pid();
SELECT pid, state, now()-xact_start AS age FROM pg_stat_activity WHERE xact_start < now() - interval '30 seconds' AND pid <> pg_backend_pid();
-- P13 (proof, by construction) existing rows cannot violate the new CHECKs: they only reference the new (NULL) columns. Nothing to run.
